-- people.original_name 초기 적재. TMDb 재호출 없이 로컬 원본 덤프에서 뽑은 값이다.
--
-- 대상은 TMDb credits에서 original_name이 name(ko-KR)과 다르고 라틴 문자이며, 검토된
-- 외국인 TMDb person ID와 정확한 original_name 쌍에 포함된 9,706명이다. 목록에 없다는
-- 이유로 외국인으로
-- 추정하지 않는다. 추출 기준과 제외 사유는 V202609221500 주석에 있다.
--
-- tmdb_person_id로 맞추므로 people.id 채번과 무관하게 재실행할 수 있다. 이미 값이 있으면
-- 덮어쓰지 않으므로 people.original_name에 가한 수동 교정은 살아남는다. 다만 이미 생성된
-- 리포트 JSON에는 도달하지 않지만, 조회 시 현재 people 데이터로 displayName을 정규화한다.
